{"type":"module"}
EOF
# A: Module._load with ESM deck
cat > a.cts <<'EOF'
const Module = require("node:module");
const orig = Module._load;
Module._load = function (req: string, ...r: unknown[]) { if (req === "pptxgenjs") { console.log("FAKE via _load"); return class { addSlide(){return {addText(){}}} }; } return orig.call(this, req, ...r); };
import("./deck-esm.ts");
EOF
echo "--- A _load + ESM"; node a.cts 2>&1 | head -5
# B: registerHooks
cat > hooks.mjs <<'EOF'
import { registerHooks } from "node:module";
registerHooks({
  resolve(spec, ctx, next) { if (spec === "pptxgenjs") return { url: "file:///fake.mjs", shortCircuit: true, format: "module" }; return next(spec, ctx); },
  load(url, ctx, next) { if (url === "file:///fake.mjs") return { format: "module", shortCircuit: true, source: "export default class { SchemeColor = {accent1:'x'}; addSlide(){return {addText(){}}} }; console.log('FAKE via registerHooks')" }; return next(url, ctx); },
});
EOF
echo "--- B registerHooks ESM"; node --import ./hooks.mjs deck-esm.ts 2>&1 | head -5
echo "--- B2 registerHooks, CJS .cts deck"
cat > deck-cjs.cts <<'EOF'
const pptxgen = require("pptxgenjs");
console.log(typeof pptxgen);
EOF
node --import ./hooks.mjs deck-cjs.cts 2>&1 | head -4
# C: DI
cat > deck-di.ts <<'EOF'
import type PptxGenJS from "pptxgenjs";
export default function build(pres: PptxGenJS): void { pres.addSlide().addText("x", {x:1,y:1,w:1,h:1}); }
EOF
cat > run-di.ts <<'EOF'
import type PptxGenJS from "pptxgenjs";
const m = await import("./deck-di.ts");
const fake = { addSlide() { return { addText() { console.log("DI call"); } }; } } as unknown as PptxGenJS;
m.default(fake);
EOF
echo "--- C DI"; node run-di.ts
# syntax checks
cat > bad.ts <<'EOF'
enum E { A }
console.log(E.A);
EOF
echo "--- enum"; node bad.ts 2>&1 | head -6
cat > imp.ts <<'EOF'
import { foo } from "./noext";
EOF
echo "--- noext"; node imp.ts 2>&1 | head -3
cat > tp.ts <<'EOF'
import { type X, y } from "./x.ts";
console.log(y);
EOF
echo "export const y=1; export type X=1" > x.ts; node tp.ts
cat > tp2.ts <<'EOF'
import { X, y } from "./x.ts";
console.log(y);
EOF
echo "--- value import of type"; node tp2.ts 2>&1 | head -4
node --no-experimental-strip-types -e 1; node --help | grep -i strip

